/* Aggregation + helpers                                              */
/* ================================================================== */
export const EXERCISES = [
    ...CHEST,
    ...CHEST_EXTRA,
    ...BACK,
    ...BACK_EXTRA,
    ...SHOULDERS,
    ...SHOULDERS_EXTRA,
    ...ARMS,
    ...ARMS_EXTRA,
    ...LEGS,
    ...LEGS_EXTRA,
    ...CORE,
    ...CORE_EXTRA,
];
export function getExerciseById(id) {
    return EXERCISES.find((e) => e.id === id);
}
export function exercisesByEquipment(allowed) {
    return EXERCISES.filter((e) => allowed.includes(e.equipment));
}
export function exercisesForMuscle(muscle) {
    return EXERCISES.filter((e) => e.primaryMuscles.includes(muscle) || e.secondaryMuscles.includes(muscle));
}
/** All muscles an exercise touches, primary first. */
export function allMusclesFor(exercise) {
    return [...exercise.primaryMuscles, ...exercise.secondaryMuscles];
}
